def magic_square_test(square):
    n = len(square)
    if any(len(row) != n for row in square):
        return False  # Not a square matrix

    # Calculate the sum of the first row to use as a reference
    target_sum = sum(square[0])

    # Check rows
    for row in square:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != target_sum:
            return False

    # Check diagonals
    if sum(square[i][i] for i in range(n)) != target_sum:
        return False
    if sum(square[i][n-1-i] for i in range(n)) != target_sum:
        return False

    return True

def reverse_vowels(s):
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    s = list(s)
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] in vowels and s[j] in vowels:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1
        elif s[i] in vowels:
            j -= 1
        elif s[j] in vowels:
            i += 1
        else:
            i += 1
            j -= 1
    return ''.join(s)

