def max_sum(triangle, rows):
    # Create a new matrix to store the maximum sums
    max_sums = [[0] * rows for _ in range(rows)]

    # Fill the bottom row of the max_sums matrix
    for i in range(rows):
        max_sums[rows - 1][i] = triangle[rows - 1][i]

    # Fill the rest of the max_sums matrix from bottom to top
    for i in range(rows - 2, -1, -1):
        for j in range(rows):
            max_sums[i][j] = triangle[i][j] + max(max_sums[i + 1][j], max_sums[i + 1][j + 1])

    return max_sums[0][0]

