def find_minimum_range(arrays):
    min_range = float('inf')
    min_start = 0
    min_end = 0
    max_val = float('-inf')

    for array in arrays:
        if len(array) == 0:
            return None

        if array[0] > max_val:
            max_val = array[0]

    while True:
        min_val = float('inf')
        min_index = -1

        for i, array in enumerate(arrays):
            if len(array) == 0:
                return None

            if array[0] < min_val:
                min_val = array[0]
                min_index = i

        if min_val == max_val:
            return (min_val, max_val)

        if min_val - max_val < min_range:
            min_range = min_val - max_val
            min_start = max_val
            min_end = min_val

        arrays[min_index].pop(0)

        if len(arrays[min_index]) == 0:
            return None

        if arrays[min_index][0] > max_val:
            max_val = arrays[min_index][0]

    return (min_start, min_end)

def find_minimum_range(arrays):
    if not arrays:
        return None

    min_heap = []
    max_value = float('-inf')
    result = None

    for i, arr in enumerate(arrays):
        if not arr:
            return None
        heapq.heappush(min_heap, (arr[0], i, 0))
        max_value = max(max_value, arr[0])

    while len(min_heap) == len(arrays):
        min_value, i, j = heapq.heappop(min_heap)
        if result is None or max_value - min_value < result[1] - result[0]:
            result = (min_value, max_value)
        if j + 1 < len(arrays[i]):
            next_value = arrays[i][j + 1]
            heapq.heappush(min_heap, (next_value, i, j + 1))
            max_value = max(max_value, next_value)

    return result
